# Commented out IPython magic to ensure Python compatibility.
#@title **Parámetros de entrenamiento**
n_images_per_batch = 4 #@param {type:"slider", min:2, max:5, step:1}
n_workers = 2 #@param ["2"] {type:"raw"}
learning_rate = 0.00025 #@param ["0.00025"] {type:"raw"}
batch_size_per_image = 256 #@param ["128","256","512"] {type:"raw"}
max_iter  = 300 #@param {type:"slider", min:300, max:1000, step:100}
ver_tensorboard = True #@param ["True", "False"] {type:"raw"}

from detectron2.engine import DefaultTrainer

cfg = get_cfg()
cfg.merge_from_file(model_zoo.get_config_file("COCO-InstanceSegmentation/mask_rcnn_R_50_FPN_3x.yaml"))
cfg.DATASETS.TRAIN = ("balloon_train",)
cfg.DATASETS.TEST = ()
cfg.DATALOADER.NUM_WORKERS = n_workers
cfg.MODEL.WEIGHTS = model_zoo.get_checkpoint_url("COCO-InstanceSegmentation/mask_rcnn_R_50_FPN_3x.yaml")  # Let training initialize from model zoo
cfg.SOLVER.IMS_PER_BATCH = n_images_per_batch
cfg.SOLVER.BASE_LR = learning_rate  # pick a good LR
cfg.SOLVER.MAX_ITER = 300    # 300 iterations seems good enough for this toy dataset; you will need to train longer for a practical dataset
cfg.SOLVER.STEPS = []        # do not decay learning rate
cfg.MODEL.ROI_HEADS.BATCH_SIZE_PER_IMAGE = batch_size_per_image   # faster, and good enough for this toy dataset (default: 512)
cfg.MODEL.ROI_HEADS.NUM_CLASSES = 1  # only has one class (ballon). (see https://detectron2.readthedocs.io/tutorials/datasets.html#update-the-config-for-new-datasets)


os.makedirs(cfg.OUTPUT_DIR, exist_ok=True)
trainer = DefaultTrainer(cfg)
trainer.resume_or_load(resume=False)
trainer.train()

